#!/usr/bin/env python3
"""Staging-only cache capability certification. Default plans have no DB effects.

Evidence is an operator trust boundary, never generated by this tool. A protocol
self-report or clean-image publication alone is not cache certification.
"""
import argparse,base64,hashlib,math,importlib.util,json,os,re,shlex,stat,subprocess,sys,time
from pathlib import Path
HERE=Path(__file__).resolve().parent
HASH=re.compile(r'[a-f0-9]{64}\Z');ID=re.compile(r'[A-Za-z0-9_.:-]{1,180}\Z')
CAP_KEYS={'version','runtimeSha256','environmentCacheVersion','secretFreeSourceBundleVersion','retainedTaskStorageAbsentRequired','credentialFreePreparationRequired','preparationCaptureVersion'}
PINS={'runtimeSha256','supervisorSha256','serviceSha256','manifestSha256','helperSha256'}
IDENTITY=('version','ownerId','projectId','repositoryIdentity','provider','architecture','baseReleaseId','baseArtifactId','baseArtifactVersion','baseRuntimeSha256','recipeSource','recipeDigest','sourceCommit','dependencyInputs')
DOCS={'capability.json','prepared-stamp.json','capture.json','restore.json','cleanup.json','pre-capture.json','filesystem.json'}
MARKER='.zuse-cache-certification/dependency-marker.txt'
class Rejected(ValueError):pass
def require(value,code):
 if not value:raise Rejected('project_cache_cert_'+code)
def canonical(v):return json.dumps(v,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()
def digest(b):return hashlib.sha256(b).hexdigest()
def exact(v,keys,code):require(isinstance(v,dict) and set(v)==set(keys),code)
def is_hash(v):return isinstance(v,str) and HASH.fullmatch(v) is not None
def is_version(v):return isinstance(v,str) and re.fullmatch(r'[1-9][0-9]{0,19}',v) is not None and int(v)<2**64
def identifier(v):return isinstance(v,str) and ID.fullmatch(v) is not None
def read(path,limit=1048576):
 path=Path(path)
 for p in (path,*path.parents):require(not p.is_symlink(),'input_symlink')
 fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_CLOEXEC)
 try:
  m=os.fstat(fd);require(stat.S_ISREG(m.st_mode) and m.st_nlink==1 and m.st_uid in (0,os.getuid()) and not m.st_mode&0o077 and m.st_size<=limit,'private_input_required')
  b=os.read(fd,limit+1);n=os.fstat(fd);require(len(b)<=limit and (m.st_dev,m.st_ino,m.st_size,m.st_mtime_ns,m.st_ctime_ns)==(n.st_dev,n.st_ino,n.st_size,n.st_mtime_ns,n.st_ctime_ns),'input_changed');return b
 finally:os.close(fd)
def decode(raw):
 def pairs(items):
  out={}
  for k,v in items:require(k not in out,'duplicate_json_key');out[k]=v
  return out
 return json.loads(raw,object_pairs_hook=pairs,parse_constant=lambda _v:(_ for _ in ()).throw(Rejected('project_cache_cert_invalid_json_number')))
def load(path):return decode(read(path))
def module(name):
 sys.dont_write_bytecode=True;s=importlib.util.spec_from_file_location('cache_cert_'+name,HERE/(name+'.py'));m=importlib.util.module_from_spec(s);s.loader.exec_module(m);return m
def sources():return {n:digest((HERE/n).read_bytes()) for n in ('project-cache-certification.py','database.py','managed-base-release.py','managed-base-fresh-boot-loader.py')}
def identity_key(v):
 exact(v,IDENTITY,'identity_fields');require(type(v['version']) is int and v['version']==1 and v['provider']=='boxd' and v['architecture'] in ('x86_64','aarch64') and v['recipeSource'] in ('project','repository'),'identity_invalid')
 for k in ('ownerId','projectId','baseReleaseId','baseArtifactId'):require(identifier(v[k]),'identity_invalid')
 require(isinstance(v['repositoryIdentity'],str) and re.fullmatch(r'github\.com/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+',v['repositoryIdentity']),'identity_invalid')
 require(is_version(v['baseArtifactVersion']) and is_hash(v['baseRuntimeSha256']) and is_hash(v['recipeDigest']) and isinstance(v['sourceCommit'],str) and re.fullmatch('[a-f0-9]{40}|[a-f0-9]{64}',v['sourceCommit']),'identity_invalid')
 dep=v['dependencyInputs'];require(isinstance(dep,dict) and len(dep)<=128,'identity_invalid')
 for p,h in dep.items():require(isinstance(p,str) and len(p)<=1024 and all(c.isascii() and c.isprintable() for c in p) and not p.startswith('/') and '\\' not in p and all(x not in ('','..','.') for x in p.split('/')) and isinstance(h,str) and re.fullmatch('[a-f0-9]{40}|[a-f0-9]{64}',h),'identity_invalid')
 typed={k:(dict(sorted(dep.items())) if k=='dependencyInputs' else v[k]) for k in IDENTITY}
 return digest(json.dumps(typed,separators=(',',':'),ensure_ascii=False).encode())
def validate_release(release,report,raw_report):
 require(isinstance(release,dict) and set(release)<={'provider','releaseId','artifactId','providerArtifactBinding','initialRuntimeBootstrap','architecture','capabilities','manifest','harnesses','certificationReportSha256'},'base_release_fields')
 module('managed-base-release').validate_release(release)
 require(release.get('provider')=='boxd' and release.get('architecture') in ('x86_64','aarch64') and release.get('releaseId')==release['manifest'].get('buildId'),'base_release_invalid')
 require(release.get('certificationReportSha256')==digest(raw_report),'base_report_digest')
 expected=digest(canonical({k:v for k,v in release.items() if k!='certificationReportSha256'}))
 expected_cases={(a,c) for a in ('claude','codex','grok') for c in module('managed-base-release').CASES}
 exact(report,{'schema','status','runId','provider','releaseSha256','driverSha256','cases','cleanupVerified'},'base_report_fields')
 require(type(report.get('schema')) is int and report.get('schema')==1 and report.get('status')=='passed' and report.get('cleanupVerified') is True and report.get('provider')=='boxd' and report.get('releaseSha256')==expected and identifier(report.get('runId')) and is_hash(report.get('driverSha256')),'base_report_not_complete')
 cases=report.get('cases');require(isinstance(cases,list),'base_cases_incomplete')
 for case in cases:
  exact(case,{'agent','case','passed','elapsedMs'},'base_case_fields');require(type(case['elapsedMs']) in (int,float) and math.isfinite(case['elapsedMs']) and case['elapsedMs']>=0,'base_case_duration')
 require(isinstance(cases,list) and len(cases)==len(expected_cases) and {(v.get('agent'),v.get('case')) for v in cases}==expected_cases and all(v.get('passed') is True for v in cases),'base_cases_incomplete')
 spec=release.get('initialRuntimeBootstrap');exact(spec,{'version','mode'}|PINS,'base_bootstrap_required');require(type(spec['version']) is int and spec['version']==1 and spec['mode']=='stopped-memory-snapshot-v1' and all(is_hash(spec[k]) for k in PINS),'base_bootstrap_invalid');return spec

def bootstrap(proof,release,op,key,machine):
 exact(proof,{'request','receipt'},'bootstrap_evidence');q=proof['request'];r=proof['receipt'];exact(q,{'version','provider','purpose','operationId','workspaceId','generation','storageIncarnationId','sourceMachineId','imagePins'},'bootstrap_request')
 expected=dict(version=1,provider='boxd',purpose='cache-preparation',operationId=op,workspaceId='cache:'+key,generation=1,storageIncarnationId='cache:'+op,sourceMachineId=machine,imagePins={k:release['initialRuntimeBootstrap'][k] for k in PINS})
 require(type(q.get('version')) is int and type(q.get('generation')) is int and q==expected and all(canonical(r.get(k))==canonical(v) for k,v in q.items()) and r.get('status')=='ready' and r.get('requestSha256')==digest(canonical(q)),'bootstrap_binding')
 exact(r,set(q)|{'status','requestSha256','unitStartSubmitted','resident'},'bootstrap_receipt');v=r['resident'];exact(v,{'residentPid','residentStartTicks','bootNonceSha256','ipcVerified','unbound','childAlive','recoveryAlive'},'bootstrap_resident')
 require(type(v['residentPid']) is int and v['residentPid']>1 and type(v['residentStartTicks']) is int and v['residentStartTicks']>0 and is_hash(v['bootNonceSha256']) and v['ipcVerified'] is True and v['unbound'] is True and v['childAlive'] is False and v['recoveryAlive'] is False and type(r['unitStartSubmitted']) is bool,'bootstrap_not_idle')

def validate_evidence(release,directory):
 directory=Path(directory);raw=read(directory/'evidence.json');m=decode(raw);exact(m,{'version','kind','provider','releaseId','baseArtifactId','baseArtifactVersion','runtimeSha256','operationId','cacheKey','documents'},'evidence_fields')
 require(type(m['version']) is int and m['version']==1 and m['kind']=='project-cache-capability-evidence-v1' and m['provider']=='boxd' and m['releaseId']==release['releaseId'] and m['baseArtifactId']==release['artifactId'] and is_version(m['baseArtifactVersion']) and m['runtimeSha256']==release['initialRuntimeBootstrap']['runtimeSha256'] and identifier(m['operationId']) and is_hash(m['cacheKey']),'evidence_binding')
 exact(m['documents'],DOCS,'evidence_inventory');docs={};pins={}
 for name,h in m['documents'].items():
  require(is_hash(h),'evidence_digest');b=read(directory/name);require(digest(b)==h,'evidence_digest');docs[name]=decode(b);pins[name]=h
 cap=docs['capability.json'];exact(cap,CAP_KEYS,'capability_fields');require(all(type(cap[k]) is int for k in ('version','environmentCacheVersion','secretFreeSourceBundleVersion','preparationCaptureVersion')) and all(type(cap[k]) is bool for k in ('retainedTaskStorageAbsentRequired','credentialFreePreparationRequired')) and cap==dict(version=1,runtimeSha256=m['runtimeSha256'],environmentCacheVersion=1,secretFreeSourceBundleVersion=1,retainedTaskStorageAbsentRequired=True,credentialFreePreparationRequired=True,preparationCaptureVersion=1),'capability_invalid')
 stamp=docs['prepared-stamp.json'];exact(stamp,{'version','identity','receipt'},'prepared_fields');i=stamp['identity'];key=identity_key(i);require(type(stamp['version']) is int and stamp['version']==1 and key==m['cacheKey'] and all(i[k]==m[v] for k,v in [('provider','provider'),('baseReleaseId','releaseId'),('baseArtifactId','baseArtifactId'),('baseArtifactVersion','baseArtifactVersion'),('baseRuntimeSha256','runtimeSha256')]) and i['architecture']==release['architecture'],'prepared_identity')
 prepared=stamp['receipt'];expected=dict(version=1,cacheKey=key,operationId=m['operationId'],runtimeSha256=m['runtimeSha256'],recipeDigest=i['recipeDigest'],dependencyDigest=digest(json.dumps([i['sourceCommit'],dict(sorted(i['dependencyInputs'].items()))],separators=(',',':'),ensure_ascii=False).encode()),sourceCommit=i['sourceCommit'],sourceBundleSha256=prepared.get('sourceBundleSha256'),credentialsRemoved=True,taskStorageAbsent=True,agentProfilesAbsent=True,secretFreeSource=True)
 require(all(prepared.get(k) is True for k in ('credentialsRemoved','taskStorageAbsent','agentProfilesAbsent','secretFreeSource')) and type(prepared.get('version')) is int and is_hash(expected['sourceBundleSha256']) and prepared==expected,'preparation_receipt')
 c=docs['capture.json'];exact(c,{'state','receipt'},'capture_fields');v=c['receipt'];exact(v,{'version','preparationCaptureVersion','cacheKey','operationId','runtimeSha256','preparedReceiptSha256','hygiene'},'capture_receipt_fields')
 require(c['state']=='ready' and type(v['version']) is int and type(v['preparationCaptureVersion']) is int and all(v[k]==x for k,x in dict(version=1,preparationCaptureVersion=1,cacheKey=key,operationId=m['operationId'],runtimeSha256=m['runtimeSha256'],preparedReceiptSha256=pins['prepared-stamp.json']).items()),'capture_binding')
 h=v['hygiene'];exact(h,{'version','operationId','runtimeSha256','atomicStopAcknowledged','legacyBuilder','originalResidentExited','supervisorLockReleased','runtimeDataAbsent','enabledBootServiceRetained','residentPid','residentStartTicks','bootServiceSha256','bootNonceSha256','removed'},'hygiene_fields')
 require(type(h['version']) is int and h['version']==1 and h['operationId']==m['operationId'] and h['runtimeSha256']==m['runtimeSha256'] and h['legacyBuilder'] is False and all(h[k] is True for k in ('atomicStopAcknowledged','originalResidentExited','supervisorLockReleased','runtimeDataAbsent','enabledBootServiceRetained')) and type(h['residentPid']) is int and h['residentPid']>1 and type(h['residentStartTicks']) is int and h['residentStartTicks']>0 and h['bootServiceSha256']==release['initialRuntimeBootstrap']['serviceSha256'] and is_hash(h['bootNonceSha256']) and isinstance(h['removed'],list) and 'supervisor.lock' in h['removed'] and set(h['removed'])<={'supervisor.lock','supervisor.json','control.sock'},'capture_hygiene')
 r=docs['restore.json'];exact(r,{'version','status','operationId','cacheKey','builderId','builderName','verifierId','verifierName','artifactId','artifactName','artifactVersion','sourceVerified','builderBootstrap','verifierBootstrap','restoredStampSha256','captureStatus','runtimeSha256'},'restore_fields')
 require(type(r['version']) is int and r['version']==1 and r['status']=='passed' and r['operationId']==m['operationId'] and r['cacheKey']==key and r['runtimeSha256']==m['runtimeSha256'] and r['sourceVerified'] is True and r['restoredStampSha256']==pins['prepared-stamp.json'] and canonical(r['captureStatus'])==canonical(c),'restore_binding')
 for k in ('builderId','verifierId','artifactId','builderName','verifierName','artifactName','artifactVersion'):require(identifier(r[k]),'resource_identity')
 require(is_version(r['artifactVersion']) and r['builderId']!=r['verifierId'] and r['artifactId']!=m['baseArtifactId'],'resource_identity')
 suffix=m['operationId'].removeprefix('cacheop_');require((r['builderName'],r['verifierName'],r['artifactName'])==('pc-b-'+suffix,'pc-v-'+suffix,'pc-s-'+suffix),'resource_names')
 bootstrap(r['builderBootstrap'],release,m['operationId'],key,r['builderId']);bootstrap(r['verifierBootstrap'],release,m['operationId'],key,r['verifierId'])
 intent=docs['pre-capture.json'];exact(intent,{'version','phase','operationId','cacheKey','builderId','expectedHead','expectedMarker','preparedStampSha256','createdAtMs'},'capture_intent_fields')
 marker=intent['expectedMarker'];exact(marker,{'path','sha256','bytes'},'marker_fields')
 require(type(intent['version']) is int and intent['version']==1 and intent['phase']=='capture-intent' and intent['operationId']==m['operationId'] and intent['cacheKey']==key and intent['builderId']==r['builderId'] and intent['expectedHead']==i['sourceCommit'] and intent['preparedStampSha256']==pins['prepared-stamp.json'] and type(intent['createdAtMs']) is int and intent['createdAtMs']>0,'capture_intent_binding')
 require(marker['path']==MARKER and is_hash(marker['sha256']) and type(marker['bytes']) is int and 1<=marker['bytes']<=4096,'marker_invalid')
 fs=docs['filesystem.json'];exact(fs,{'version','operationId','cacheKey','captureIntentSha256','captureObservedAtMs','builder','restored'},'filesystem_fields')
 require(type(fs['version']) is int and fs['version']==1 and fs['operationId']==m['operationId'] and fs['cacheKey']==key and fs['captureIntentSha256']==pins['pre-capture.json'] and type(fs['captureObservedAtMs']) is int and fs['captureObservedAtMs']>=intent['createdAtMs'],'filesystem_capture_binding')
 for role,machine in [('builder',r['builderId']),('restored',r['verifierId'])]:
  observed=fs[role];exact(observed,{'machineId','head','marker','symlinksRejected','readOnly','observedAtMs'},'filesystem_observation_fields')
  require(observed['machineId']==machine and observed['head']==intent['expectedHead'] and canonical(observed['marker'])==canonical(marker) and observed['symlinksRejected'] is True and observed['readOnly'] is True and type(observed['observedAtMs']) is int and observed['observedAtMs']>0,'filesystem_readback')
 require(fs['builder']['observedAtMs']<=intent['createdAtMs']<=fs['captureObservedAtMs']<=fs['restored']['observedAtMs'],'filesystem_order')
 clean=docs['cleanup.json'];exact(clean,{'version','independentlyVerified','operationId','checks','allAbsent'},'cleanup_fields');require(type(clean['version']) is int and clean['version']==1 and clean['independentlyVerified'] is True and clean['operationId']==m['operationId'] and clean['allAbsent'] is True,'cleanup_incomplete')
 expected={('machine',r[k]) for k in ('builderId','builderName','verifierId','verifierName')}|{('snapshot',r[k]) for k in ('artifactId','artifactName')};checks=clean['checks'];require(isinstance(checks,list) and len(checks)==6,'cleanup_incomplete')
 seen=set()
 for check in checks:
  exact(check,{'kind','reference','providerNotFound'},'cleanup_check');require(check['providerNotFound'] is True,'cleanup_incomplete');seen.add((check['kind'],check['reference']))
 require(seen==expected,'cleanup_identity')
 return cap,{'evidence.json':digest(raw),**pins},m

def validated_inputs(release_path,base_report,directory):
 raw=read(release_path);release=decode(raw);report_raw=read(base_report);validate_release(release,decode(report_raw),report_raw);cap,pins,evidence=validate_evidence(release,directory)
 plan={'version':1,'kind':'staging-project-cache-certification-v1','environment':'staging','schema':'zuse_staging','provider':'boxd','releaseId':release['releaseId'],'artifactId':release['artifactId'],'runtimeSha256':cap['runtimeSha256'],'architecture':release['architecture'],'receipt':cap,'releaseSha256':digest(raw),'baseCertificationReportSha256':digest(report_raw),'evidenceSha256':pins,'sourceSha256':sources(),'operationId':evidence['operationId'],'databaseVerified':False,'applyRequiresExactVerifiedBase':True,'providerEffects':False}
 return plan,release

def make_plan(release_path,base_report,directory):return validated_inputs(release_path,base_report,directory)[0]

def sql(plan,release):
 db=module('database');lit=db.literal;tag='$cachecert_'+digest(canonical(release))+'$';require(tag not in canonical(release).decode(),'sql_binding_invalid');rel=lit(canonical(release).decode());receipt=lit(canonical(plan['receipt']).decode());p=lit(plan['provider']);r=lit(plan['releaseId']);runtime=lit(plan['runtimeSha256']);arch=lit(plan['architecture']);artifact=lit(plan['artifactId'])
 return f"""BEGIN;
SET LOCAL search_path=zuse_staging,pg_catalog;
SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='15s';
SELECT pg_advisory_xact_lock(hashtextextended('project-cache-cert:'||{p}||':'||{r},0));
DO {tag} BEGIN
IF current_schema()<>'zuse_staging' OR NOT EXISTS(SELECT 1 FROM zuse_cloud_schema_identity WHERE singleton AND environment='staging') THEN RAISE EXCEPTION 'project_cache_cert_staging_identity'; END IF;
IF current_user IN ('zuse_cloud_staging','zuse_cloud_production') OR NOT has_table_privilege(current_user,'cloud_project_cache_capabilities','INSERT') OR NOT has_table_privilege(current_user,'cloud_project_cache_capabilities','UPDATE') THEN RAISE EXCEPTION 'project_cache_cert_operator_role'; END IF;
PERFORM 1 FROM cloud_managed_bases WHERE provider={p} AND release_id={r} AND state='verified' AND artifact_id={artifact} AND architecture={arch} AND runtime_manifest={rel}::jsonb FOR SHARE;
IF NOT FOUND THEN RAISE EXCEPTION 'project_cache_cert_verified_base_required'; END IF;
PERFORM 1 FROM cloud_project_cache_capabilities WHERE provider={p} AND release_id={r} FOR UPDATE;
IF EXISTS(SELECT 1 FROM cloud_project_cache_capabilities WHERE provider={p} AND release_id={r} AND (state<>'certified' OR runtime_sha256<>{runtime} OR architecture<>{arch} OR receipt<>{receipt}::jsonb)) THEN RAISE EXCEPTION 'project_cache_cert_replay_mismatch'; END IF;
INSERT INTO cloud_project_cache_capabilities(provider,release_id,runtime_sha256,architecture,receipt,state,certified_at) VALUES({p},{r},{runtime},{arch},{receipt}::jsonb,'certified',(extract(epoch FROM clock_timestamp())*1000)::bigint) ON CONFLICT DO NOTHING;
END {tag};
SELECT json_build_object('status','certified','environment','staging','provider',{p},'releaseId',{r},'schema',current_schema());
COMMIT;"""

def apply(plan_path,approved,release_path,base_report,directory,url_file,receipt_path):
 raw=read(plan_path);require(digest(raw)==approved,'approved_plan_required');plan=decode(raw);current,release=validated_inputs(release_path,base_report,directory);require(plan==current,'plan_changed');require(not Path(receipt_path).exists(),'inspect_original_apply');intent=Path(str(receipt_path)+'.intent.json');require(not intent.exists(),'inspect_original_apply');url=read(url_file,16384).decode().strip();db=module('database');env=db.connection_environment(url,inherited={});env['PGAPPNAME']='zuse-project-cache-certification';statement=sql(plan,release);write_new(intent,{'version':1,'phase':'apply-intent','planSha256':approved,'releaseId':plan['releaseId'],'evidenceSha256':plan['evidenceSha256'],'statementSha256':digest(statement.encode())});command=['psql','-X','--no-password','-Atq','-v','ON_ERROR_STOP=1']
 # No blind write retry: a lost COMMIT response requires a fresh reviewed plan
 # and read-only inspection of the original immutable row.
 result=subprocess.run(command,input=statement,env=env,text=True,capture_output=True,timeout=30)
 if result.returncode:
  known=re.search(r'project_cache_cert_[a-z_]+',result.stderr);raise Rejected(known.group() if known else 'project_cache_cert_database_rejected')
 rows=[json.loads(v) for v in result.stdout.splitlines() if v.startswith('{')];require(rows and rows[-1].get('status')=='certified' and rows[-1].get('schema')=='zuse_staging','database_receipt')
 write_new(receipt_path,{'version':1,'status':'certified','environment':'staging','planSha256':approved,'releaseId':plan['releaseId'],'runtimeSha256':plan['runtimeSha256'],'evidenceSha256':plan['evidenceSha256'],'providerEffects':False});return rows[-1]
def inspect_original(plan_path,approved,release_path,base_report,directory,url_file,receipt_path):
 raw=read(plan_path);require(digest(raw)==approved,'approved_plan_required');plan=decode(raw);current,release=validated_inputs(release_path,base_report,directory);require(plan==current,'plan_changed')
 intent=load(str(receipt_path)+'.intent.json');require(intent.get('planSha256')==approved and intent.get('releaseId')==plan['releaseId'],'original_intent_mismatch')
 db=module('database');lit=db.literal;require(intent.get('evidenceSha256')==plan['evidenceSha256'] and intent.get('statementSha256')==digest(sql(plan,release).encode()),'original_intent_mismatch')
 statement="BEGIN READ ONLY;SET LOCAL search_path=zuse_staging,pg_catalog;SET LOCAL statement_timeout='10s';"
 statement+="SELECT json_build_object('schema',current_schema(),'environment',(SELECT environment FROM zuse_cloud_schema_identity WHERE singleton),'capabilityMatches',EXISTS(SELECT 1 FROM cloud_project_cache_capabilities WHERE provider="+lit(plan['provider'])+" AND release_id="+lit(plan['releaseId'])+" AND state='certified' AND runtime_sha256="+lit(plan['runtimeSha256'])+" AND architecture="+lit(plan['architecture'])+" AND receipt="+lit(canonical(plan['receipt']).decode())+"::jsonb),'baseStillVerified',EXISTS(SELECT 1 FROM cloud_managed_bases WHERE provider="+lit(plan['provider'])+" AND release_id="+lit(plan['releaseId'])+" AND state='verified' AND artifact_id="+lit(plan['artifactId'])+" AND runtime_manifest="+lit(canonical(release).decode())+"::jsonb));COMMIT;"
 env=db.connection_environment(read(url_file,16384).decode().strip(),inherited={});env['PGAPPNAME']='zuse-project-cache-certification-inspect'
 result=subprocess.run(['psql','-X','--no-password','-Atq','-v','ON_ERROR_STOP=1'],input=statement,env=env,text=True,capture_output=True,timeout=30);require(result.returncode==0,'inspection_unavailable');rows=[decode(line) for line in result.stdout.splitlines() if line.startswith('{')];require(rows and rows[-1].get('schema')=='zuse_staging' and rows[-1].get('environment')=='staging','staging_identity')
 return {'status':'original-commit-observed' if rows[-1].get('capabilityMatches') and rows[-1].get('baseStillVerified') else 'original-not-ready','planSha256':approved,'readOnly':True,'providerEffects':False,**rows[-1]}

