def write_new(path,value):
 path=Path(path)
 for parent in path.parents:require(not parent.is_symlink(),'output_symlink')
 meta=path.parent.stat();require(stat.S_ISDIR(meta.st_mode) and meta.st_uid in (0,os.getuid()) and not meta.st_mode&0o022,'private_output_directory_required')
